<?php function inputField($label,$name,$type='text',$value='',$required=false){ ?><label class="field"><span><?=e($label)?><?=$required?' <i>*</i>':''?></span><input name="<?=e($name)?>" type="<?=e($type)?>" value="<?=e($value)?>" placeholder="Introduza <?=strtolower(e($label))?>" <?=$required?'required':''?>></label><?php } function selectField($label,$name,$options){ ?><label class="field"><span><?=e($label)?></span><select name="<?=e($name)?>"><?php foreach($options as $o): ?><option><?=e($o)?></option><?php endforeach ?></select></label><?php } ?>